"""Generate intrinsic dimensions for responsive portfolio images."""

import json
from pathlib import Path

from PIL import Image


ROOT = Path(__file__).resolve().parents[1]
images = {}
for path in sorted((ROOT / "assets" / "img").glob("*.webp")):
    with Image.open(path) as image:
        images[path.stem] = [image.width, image.height]

target = ROOT / "js" / "image-sizes.js"
target.write_text(
    "/* Generated by _work/generate-image-sizes.py. */\n"
    "window.PORTFOLIO_IMAGE_SIZES = "
    + json.dumps(images, ensure_ascii=False, separators=(",", ":"))
    + ";\n",
    encoding="utf-8",
)
print(f"Wrote {len(images)} image dimensions to {target}")
